        payload_desc = "Multispectral imager with visible and near-IR bands"
        data_rate = "100 Mbps peak"
        power_consumption = "30W operational"
    elif "communication" in mission_type.lower():
        payload_desc = "S-band/UHF transponder for store-and-forward communications"
        data_rate = "10 Mbps peak"
        power_consumption = "40W operational"
    else:
        payload_desc = "Mission-specific payload"
        data_rate = "20 Mbps peak"
        power_consumption = "20W operational"

