                "consumption": {
                    "payload": power_consumption,
                    "bus": "15-25W depending on mode",
                    "margin": "15%"
                }
            },
            "payload_summary": {
                "primary": payload_desc,
                "data_rate": data_rate,
                "thermal_control": "Passive radiators + active heating/cooling as needed"
